entries[98113] = { ["name"] = "Stack of Letters", ["text"] = "Binds when picked up\n\"Correspondence from a loved one in rough, Orcish script.\"\nSell Price:" }
entries[98114] = { ["name"] = "Pet Treat", ["text"] = "Binds to account\nUse: Battle pet experience gained is increased by 50% for 1 hour.\n\"Twice the ingredients of the leading alternative.\"\nSell Price:" }
entries[98115] = { ["name"] = "Trophy Necklace", ["text"] = "Binds when picked up\n\"Most of the tusks appear to be from Quillboars or Kodos. Some of the fresh tusks are not.\"\nSell Price:" }
entries[98116] = { ["name"] = "Freeze-Dried Hyena Jerky", ["text"] = "Requires Level 85\nUse: Restores 199999 health and ( 50000 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will move more quickly while in the Northern Barrens for 1 hour.\nSell Price:" }
entries[98117] = { ["name"] = "Moneybrau", ["text"] = "Unique (24)\nUse: Quaff the gold-colored brew. (1 Min Cooldown)\nSell Price:" }
entries[98118] = { ["name"] = "Scorpion Crunchies", ["text"] = "Requires Level 85\nUse: Restores 199999 health and ( 50000 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will deal more damage while in the Northern Barrens for 1 hour.\nSell Price:" }
entries[98119] = { ["name"] = "Indecipherable Plans", ["text"] = "Binds when picked up\n\"The only thing to be gleaned from this mess of scribbles is something about an excavation.\"\nSell Price:" }
entries[98120] = { ["name"] = "Delivery Invoice", ["text"] = "Binds when picked up\n\"A record of a large number of sealed containers being delivered to Orgrimmar.\"\nSell Price:" }
entries[98121] = { ["name"] = "Amberseed Bun", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Restores 300000 health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 200 expertise for 1 hour.\n\"For some reason, fresh amberseeds were hard to come by this year.\"\nSell Price:" }
entries[98122] = { ["name"] = "Camembert du Clefthoof", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Restores 300000 health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 200 haste for 1 hour.\n\"Milking a clefthoof is, as one might predict, extraordinarily difficult.\"\nSell Price:" }
entries[98123] = { ["name"] = "Whale Shark Caviar", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Restores 300000 health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 200 critical strike for 1 hour.\n\"Has a very salty taste, similar to tears.\"\nSell Price:" }
entries[98124] = { ["name"] = "Bloodberry Tart", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Restores 300000 health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 200 parry for 1 hour.\n\"Bloodberries are actually quite common, but almost nobody goes to Quel'Danas to pick them anymore.\"\nSell Price:" }
entries[98125] = { ["name"] = "Shaved Zangar Truffles", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Restores 300000 health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 200 dodge for 1 hour.\n\"Only a very small part of the Zangar Truffle is not poisonous. This is that part.\"\nSell Price:" }
entries[98126] = { ["name"] = "Mechanopeep Foie Gras", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Restores 300000 health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 200 hit for 1 hour.\n\"We guarantee that our mechanopeeps have been treated humanely, and not force-oiled.\"\nSell Price:" }
entries[98127] = { ["name"] = "Dented Can of Kaja'Cola", ["text"] = "Binds when picked up\nRequires Level 90\nUse: Restores 300000 health and ( 75000 / 5 * 20) mana over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating you will become well fed and gain 200 mastery for 1 hour.\n\"These are incredibly hard to find. Only a few cans remain.\"\nSell Price:" }
